// Fork of "Rocket Tycoon" by wyatt. https://shadertoy.com/view/sdscRX
// 2025-01-20 17:49:43

Main {
    vec4 q = A(U);
    Q = max(sin(-4.-q.z-q.w+vec4(1,2,3,4)),0.);
    Q.w = min(q.w,1.);
    get_rocket
    vec2 u = U;

    if (a.y>RH.y*R.y) u.y += a.y-(RH*R).y,u.x+=a.x;
    vec4 c = sin(-1.5+u.y/R.y+vec4(1,2,3,5))*exp(-u.y/R.y);
    c += pow(hash(vec4(floor(u),1,1)).x,40.)*(1.-exp(-u.y/R.y));
    Q = mix(c,Q,Q.w);

    Q += .3*max(max(1.-10.*Q.w,0.)*sin(-3.-3.*q.z+vec4(1,2,3,4)),0.);
}

#define R iResolution.xy
#define A(U) texture(iChannel0,(U)/R)
#define B(U) texture(iChannel1,(U)/R)
#define C(U) texture(iChannel2,(U)/R)
#define D(U) texture(iChannel3,(U)/R)
#define Main void mainImage(out vec4 Q, in vec2 U) 
#define ei(a) mat2(cos(a),-sin(a),sin(a),cos(a))
#define ve(a) vec2(cos(a),sin(a))
#define RH (vec2(.5+.05*da.x,.66+.05*da.y))
#define sin(a) sin(mod(floor(a)+floor(fract(a)*1000.)/1000.,2.*3.1415926))

// Size of Bottle Rocket :
#define S vec2(30.,140.)
// Pressure of Engine :
#define ENGINE .999
// Mass of Rocket :
#define MASS 25.
#define N (S.y*2.)
#define pi 3.14159265359
#define get_rocket vec4 a = B(vec2(0,0)+.5);vec4 da = B(vec2(1,0)+.5);
#define loop_rocket for (float i = -N; i < N; i++) {float y = 2.8*i/N+1.9;vec2 v1 = vec2(S.x*(-1.+(1.-exp(-.001*y*y*y*y*y*y))),i/N*S.y)*ei(a.z); vec2 v2 = vec2(S.x*(1.-(1.-exp(-.001*y*y*y*y*y*y))),i/N*S.y)*ei(a.z);
vec4 rocket (vec2 U, vec4 a, vec4 da) {
    U -= a.xy;
    vec2 u = abs(U*ei(-a.z))-S;
    if (max(u.x,u.y)>4.) return vec4(0);
    float d = 1e9;
    vec2 v = vec2(0);
    loop_rocket
        float l1 = length(U-v1);
        if (l1<d) {
            d = l1;
            v = da.xy + vec2(-v1.y,v1.x)*da.z;
        }
        float l2 = length(U-v2);
        if (l2<d) {
            d = l2;
            v = da.xy + vec2(-v2.y,v2.x)*da.z;
        }
    }
    return vec4(v,0,1)*smoothstep(2.5,1.5,abs(d));
}
vec4 hash(vec4 p) {
                const vec4 k = vec4(0.1031, 0.11369, 0.13787, 0.16379); 
                p = fract(p * k);                                       
                p += dot(p, p.wxyz + k);                                
                p = fract((p.xxyz + p.yzww) * p.zyxw);                  
                return fract(sin(p) * 43758.5453);                      
            }

Main {
    get_rocket
    vec2 u = U;
    if (a.y>RH.y*R.y) u.y += a.y-(RH*R).y;
    if (a.y>RH.y*R.y) U += da.xy, a.y = (RH*R).y;
    vec4 c = C(U);
    Q = A(U-c.xy);


    Q.xy -= .5*C(U-c.xy).zw*clamp(exp(-.3*u.y/R.y)+Q.w,0.1,1.);
    if (length(U-a.xy+vec2(0,.5*S.y)*ei(a.z))<15.) Q.z = ENGINE, Q.w = 1.;
    vec4 v = rocket(U,a,da);
    Q.xyw = mix(Q.xyw,vec3(v.xy,0),v.w);
    if (U.y<R.y&&(U.x<1.||R.x-U.x<1.)) Q.xy *= 0.;
    if (U.y<1.) Q.xy *= 0.;
    if (R.y-U.y<1.) Q *= 0.;
}

Main {
    Q = A(U);
    vec4 
        n = A(U+vec2(0,1)),
        e = A(U+vec2(1,0)),
        s = A(U-vec2(0,1)),
        w = A(U-vec2(1,0));

    get_rocket
    vec2 u = U;

    if (a.y>RH.y*R.y) u.y += a.y-(RH*R).y;

    Q.z -= .5*(e.x-w.x+n.y-s.y);
    //Q.z = clamp(Q.z,-1.,1.);
}

Main {
    Q = A(U);
    vec4 
        n = A(U+vec2(0,1)),
        e = A(U+vec2(1,0)),
        s = A(U-vec2(0,1)),
        w = A(U-vec2(1,0)),
        m = 0.25*(n+e+s+w);
    Q.xy = m.xy;
    Q.zw = .5*vec2(e.z-w.z,n.z-s.z)+.2*vec2(e.w-w.w,n.w-s.w);

}

Main {
    if (U.x>2.||U.y>2.) discard;

    get_rocket

    if (iFrame < 1) a = vec4(.5*R.x,S.y+4.,0,0);
    vec4 f = vec4(0);

    loop_rocket
        if (i<-.5*N) continue;
        vec2 u = a.xy;
        if (u.y>RH.y*R.y) u.y = (RH*R).y;
        {
            vec2 im = -.1*A(u+v1).zw/N;
            if (length(im)>0.&&length(v1)>0.) {
                f.z -= .01*dot(v1,vec2(-im.y,im.x));
                f.xy += im*abs(dot(normalize(v1),normalize(im)));
            }
        }
        {
            vec2 im = -.1*A(u+v2).zw/N;
            if (length(im)>0.&&length(v2)>0.) {
                f.z -= .01*dot(v2,vec2(-im.y,im.x));
                f.xy += im*abs(dot(normalize(v2),normalize(im)));
            }
        }
    }
    da += f/MASS;
    da.y -= .1/R.y;
    a += da;


    if (U.x<1.) Q = a;
    else        Q = da;
}
